// src/components/dashboard/trending-coffee.tsx
import Image from 'next/image';

const trendingCoffeeData = [
  {
    name: 'Cappuccino',
    price: '$85.00',
    sales: '240',
    image: '/cappuccino.png', // Pastikan kamu punya gambar ini di folder public
  },
  {
    name: 'Latte',
    price: '$70.50',
    sales: '220',
    image: '/latte.png',
  },
  {
    name: 'Frappuccino',
    price: '$82.50',
    sales: '200',
    image: '/frappuccino.png',
  },
  {
    name: 'Mocha',
    price: '$40.50',
    sales: '100',
    image: '/mocha.png',
  },
];

const TrendingCoffee = () => {
  return (
    <div className="bg-white p-6 rounded-2xl">
      <div className="flex justify-between items-center mb-6">
        <h3 className="font-bold text-lg">Trending Coffee</h3>
        <a href="#" className="text-sm text-brand-text-secondary">See all</a>
      </div>
      <div className="space-y-4">
        {trendingCoffeeData.map((coffee, index) => (
          <div key={index} className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              {/* Ganti dengan komponen Image jika path gambar sudah benar */}
              <div className="w-10 h-10 bg-gray-200 rounded-md flex items-center justify-center">
                 <Image src={coffee.image} alt={coffee.name} width={32} height={32} />
              </div>
              <div>
                <p className="font-semibold text-sm">{coffee.name}</p>
                <p className="text-xs text-brand-text-secondary">{coffee.price}</p>
              </div>
            </div>
            <p className="font-bold text-gray-700">{coffee.sales}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TrendingCoffee;