// src/components/dashboard/stat-card.tsx
import { ReactNode } from 'react';

interface StatCardProps {
  icon: ReactNode;
  title: string;
  value: string;
  change: string;
  changeType: 'increase' | 'decrease';
}

const StatCard = ({ icon, title, value, change, changeType }: StatCardProps) => {
  const changeColor = changeType === 'increase' ? 'text-green-500' : 'text-red-500';

  return (
    <div className="bg-white p-6 rounded-2xl flex-1">
      <div className="flex items-center justify-between mb-2">
        <p className="text-brand-text-secondary">{title}</p>
        <div className="p-2 bg-gray-100 rounded-md">{icon}</div>
      </div>
      <h3 className="text-3xl font-bold mb-1">{value}</h3>
      <div className="w-full bg-gray-200 rounded-full h-1.5">
        <div className="bg-orange-400 h-1.5 rounded-full" style={{ width: '75%' }}></div>
      </div>
       <p className={`text-sm mt-2 ${changeColor}`}>{change}</p>
    </div>
  );
};

export default StatCard;